//frontend/src/store/productStore.js
import {
  createProduct,
  getAllProducts,
  getProductById,
  updateProduct,
  deleteProduct,
} from "@/services/productService.js"; // 引入服务层

// 创建一个可反应的状态对象
const state = {
  products: [], // 确保是一个数组
  product: null, // 当前单个产品
  error: null,
};

const mutations = {
  SET_PRODUCTS(state, products) {
    state.products = products; // 更新产品列表
  },
  SET_ERROR(state, error) {
    state.error = error; // 设置错误信息
  },
  SET_CURRENT_PRODUCT(state, product) {
    state.currentProduct = product; // 更新当前产品
  },
};

const getters = {};
// action 用于处理异步操作和状态更新
const actions = {
  async fetchProducts({ commit }) {
    commit("SET_ERROR", null);
    try {
      const response = await getAllProducts();
      console.log("API 返回的响应:", response);
      if (response.success) {
        commit("SET_PRODUCTS", response.data);
      } else {
        throw new Error(response.message);
      }
    } catch (error) {
      commit("SET_ERROR", error.message);
    }
  },

  async fetchProductById({ commit }, id) {
    commit("SET_ERROR", null);
    try {
      const response = await getProductById(id);
      commit("SET_CURRENT_PRODUCT", response);
    } catch (error) {
      commit("SET_ERROR", error.message);
    }
  },

  async addProduct(productData) {
    state.error = null; // 清空之前的错误信息
    try {
      const response = await createProduct(productData);
      state.products.push(response); // 将新产品添加到列表
    } catch (error) {
      state.error = error.message; // 处理错误
    }
  },

  async updateProduct(id, updatedData) {
    state.error = null; // 清空之前的错误信息
    try {
      const response = await updateProduct(id, updatedData);
      const index = state.products.findIndex((product) => product.id === id);
      if (index !== -1) {
        state.products[index] = response; // 更新产品列表中的产品
      }
    } catch (error) {
      state.error = error.message; // 处理错误
    }
  },

  async deleteProduct(id) {
    state.error = null; // 清空之前的错误信息
    try {
      await deleteProduct(id);
      state.products = state.products.filter((product) => product.id !== id); // 从列表中删除产品
    } catch (error) {
      state.error = error.message; // 处理错误
    }
  },
};

// 导出状态和 actions
export default {
  state, // 解构响应状态为 refs，以便在组件中使用
  getters,
  actions,
  mutations,
};
